// One item per active clinic, each carrying the slice of its diary that is due a
// reminder. Runs hourly and looks 24-25 hours ahead, so every appointment falls
// into exactly one pass and nobody is reminded twice.
const LEAD_HOURS = 24;
const now = Date.now();
const out = [];

for (const row of $input.all().map(i => i.json)) {
  const status = String(row.status || 'active').toLowerCase();
  if (status === 'inactive') continue;
  const id = String(row.clinic_id || '').trim();
  if (!id) continue;

  out.push({ json: {
    clinicId: id,
    name: row.name || 'the practice',
    calendarId: String(row.calendar_id || '').trim() || 'primary',
    timezone: String(row.timezone || '').trim() || 'Europe/London',
    notify_chat: String(row.notify_chat || 'YOUR_ID'),
    // which route the practice has chosen for its patients; until a patient
    // channel is live this stays 'practice' and the list goes to the clinic
    channel: String(row.reminder_channel || '').trim().toLowerCase() || 'practice',
    timeMin: new Date(now + LEAD_HOURS * 3600000).toISOString(),
    timeMax: new Date(now + (LEAD_HOURS + 1) * 3600000).toISOString()
  }});
}

return out;

// Decide who is actually due a reminder, and write what it should say.
//
// The delivery channel is deliberately not decided here. Whether this ends up as
// the practice's own email, an SMS or a WhatsApp message, the answer to "who,
// when, and what does it say" is the same — so it is settled once, here.

const clinics = $('Clinic Windows').all().map(i => i.json);
const responses = $input.all().map(i => i.json);

const sd = $getWorkflowStaticData('global');
sd._rem = sd._rem || {};
const now = Date.now();
// forget events older than a week so the ledger cannot grow without bound
for (const k in sd._rem) if (now - sd._rem[k] > 7 * 86400000) delete sd._rem[k];

const esc = (x) => String(x || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const NL = String.fromCharCode(10);
const out = [];

for (let i = 0; i < responses.length; i++) {
  const clinic = clinics[i] || clinics[0];
  if (!clinic) continue;
  const events = (responses[i] && responses[i].items) || [];
  const due = [];

  for (const e of events) {
    if (!e || e.status === 'cancelled') continue;
    const start = (e.start || {}).dateTime;
    if (!start) continue;                       // all-day blocks are not appointments

    // Keyed on the calendar, not the clinic: two clinic records pointing at one
    // diary must not each send their own copy of the same appointment.
    const key = clinic.calendarId + ':' + e.id;
    if (sd._rem[key]) continue;                 // already reminded on an earlier pass

    // The patient's contact is either on the event as a guest, or in the line the
    // assistant wrote into the description when it booked.
    const desc = String(e.description || '');
    const fromDesc = (desc.match(/^Contact:\s*(.+)$/m) || [])[1] || '';
    const guest = ((e.attendees || []).filter(a => a && a.email && !a.organizer)[0] || {}).email || '';
    const contact = String(fromDesc || guest).trim();
    const patient = (desc.match(/^Patient:\s*(.+)$/m) || [])[1] || '';

    sd._rem[key] = now;
    due.push({
      when: new Intl.DateTimeFormat('en-GB', { timeZone: clinic.timezone, weekday: 'long',
              day: 'numeric', month: 'long', hour: 'numeric', minute: '2-digit', hour12: true }).format(new Date(start)),
      summary: e.summary || 'Appointment',
      patient: patient.trim(),
      contact,
      reachable: /@/.test(contact) ? 'email' : (/\d{6,}/.test(contact) ? 'phone' : 'none')
    });
  }

  if (!due.length) continue;

  const lines = ['⏰ <b>APPOINTMENT REMINDERS DUE</b>', esc(clinic.name), ''];
  for (const d of due) {
    lines.push('<b>' + esc(d.when) + '</b>');
    lines.push(esc(d.summary) + (d.patient ? '  ·  ' + esc(d.patient) : ''));
    lines.push(d.contact ? esc(d.contact) : 'no contact on file');
    lines.push('');
  }
  lines.push('Tomorrow, 24 hours ahead. ' + due.length + ' to confirm.');

  out.push({ json: {
    clinicId: clinic.clinicId,
    notify_chat: clinic.notify_chat,
    channel: clinic.channel,
    count: due.length,
    reminders: due,
    text: lines.join(NL)
  }});
}

return out;
